// Service worker: saves the whole atlas on the device so it works with no connection.
// precache.js is generated by scripts/build_site_data.py; it lists every file and a version fingerprint.
// Only files from this site are ever cached or fetched. Nothing is sent anywhere.

importScripts("precache.js");

const { version, files } = self.ATLAS_PRECACHE;
const CACHE_PREFIX = "si-lore-";
const CACHE = CACHE_PREFIX + version;
const SHELL_URLS = ["./"].concat(files); // "./" is the page you get when you open the site's address

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // cache: "reload" skips the browser's own HTTP cache so we never save a stale copy of a file.
      // If any file fails, the install fails as a whole and the old copy keeps working.
      await Promise.all(SHELL_URLS.map((url) => cache.add(new Request(url, { cache: "reload" }))));
      await self.skipWaiting();
    })()
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE).map((key) => caches.delete(key)));
      await self.clients.claim();
    })()
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  if (new URL(request.url).origin !== self.location.origin) return;
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      const hit = await cache.match(request, { ignoreSearch: true });
      if (hit) return hit;
      if (request.mode === "navigate") {
        const shell = await cache.match("index.html");
        if (shell) return shell;
      }
      return fetch(request);
    })()
  );
});

self.addEventListener("message", (event) => {
  if (!event.data || event.data.type !== "status") return;
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      const have = (await cache.keys()).length;
      const reply = { type: "status", version, count: files.length, complete: have >= SHELL_URLS.length };
      if (event.source) event.source.postMessage(reply);
    })()
  );
});
